using System.Text;

namespace Autoredi.Generators.Emitting;

/// <summary>
/// Fluent builder for the C# sources the generator emits. Indentation is cached for the first
/// 16 levels; instance is thread-unsafe by design and created per generated file.
/// </summary>
internal sealed class CodeBuilder
{
    private const int CachedIndentLevels = 16;

    private readonly StringBuilder _buffer = new();
    private readonly List<string> _indents =
        [with(CachedIndentLevels), .. Enumerable.Range(0, CachedIndentLevels).Select(static level => new string(' ', level * 4))];
    private int _indent;

    /// <summary>
    /// Prepends the standard auto-generated header (marker line and a nullable enable) plus a blank line.
    /// </summary>
    public CodeBuilder AutoGenerated()
    {
        _buffer.Append("// <auto-generated/>\n#nullable enable\n");
        _buffer.AppendLine();
        return this;
    }

    /// <summary>
    /// Appends a line with the current indentation, or an empty line when <paramref name="text"/> is null or empty.
    /// </summary>
    public CodeBuilder Line(string text = "")
    {
        if (string.IsNullOrEmpty(text))
        {
            _buffer.AppendLine();
        }
        else
        {
            _buffer.Append(GetIndent()).AppendLine(text);
        }

        return this;
    }

    /// <summary>
    /// Appends a <c>using</c> directive when <paramref name="namespace"/> is non-empty.
    /// </summary>
    public CodeBuilder Using(string @namespace)
    {
        if (!string.IsNullOrEmpty(@namespace))
        {
            _buffer.AppendLine("using " + @namespace + ";");
        }

        return this;
    }

    /// <summary>
    /// Appends a file-scoped namespace declaration followed by an empty line.
    /// </summary>
    public CodeBuilder Namespace(string @namespace)
    {
        if (!string.IsNullOrEmpty(@namespace))
        {
            Line("namespace " + @namespace + ";");
            Line();
        }

        return this;
    }

    /// <summary>
    /// Appends a class declaration line without an opening brace.
    /// </summary>
    public CodeBuilder Class(string modifiers, string name, string? baseTypes = null)
    {
        var declaration = modifiers + " class " + name;
        if (!string.IsNullOrEmpty(baseTypes))
        {
            declaration += " : " + baseTypes;
        }

        return Line(declaration);
    }

    /// <summary>
    /// Appends a method signature line without an opening brace.
    /// </summary>
    public CodeBuilder Method(string modifiers, string returnType, string name, string parameters = "") =>
        Line(modifiers + " " + returnType + " " + name + "(" + parameters + ")");

    /// <summary>
    /// Appends a block surrounded by braces, invoking <paramref name="content"/> at an increased indent.
    /// </summary>
    public CodeBuilder Block(Action<CodeBuilder> content)
    {
        Line("{");
        _indent++;
        try
        {
            content(this);
        }
        finally
        {
            _indent--;
        }

        return Line("}");
    }

    private string GetIndent() =>
        _indent < _indents.Count ? _indents[_indent] : new string(' ', _indent * 4);

    /// <summary>
    /// Returns the built source text.
    /// </summary>
    public override string ToString() => _buffer.ToString();
}
